# -*- coding: utf-8 -*-
# Класс «разорванная десятичная дробь» в условиях («$15-1$, $12$» вместо 15 − 1,12) + связанные находки. Каждый ключ пересчитан по исправленному условию (check_v5f.py).
P = {}
D = "в условии разорвана десятичная дробь запятой-разделителем: "
def E(t, why, q, src="сверено с ключом (пересчитано)", **kw):
    P[t] = {"why": why, "q": q, "src": src + ", 26.09"}; P[t].update(kw)
E("G9_TB_ДГ5_639_2", D + "«y₁ = 1, 5» → y₁ = 1,5 (ключ 1,5; 2,5; 4,5; …)", r"Вычислите первые несколько членов последовательности $(y_{n})$, если $y_{1}=1{,}5$, $y_{n+1}-y_{n}=n$.")
E("G6_TB_37_1369.1", D + "«12+7, 8·(…)» → 12 + 7,8 · (8,1 − 8,4) = 12 − 2,34 = 9,66", r"Выполните действия $12+7{,}8 \cdot (8{,}1-8{,}4)$")
E("G6_TB_37_1369.2", D + "«−6−4, 5·(…)» → −6 − 4,5 · (5,2 − 10,6) = −6 + 24,3 = 18,3", r"Выполните действия $-6-4{,}5 \cdot (5{,}2-10{,}6)$")
E("G8_ALG_32_557.1", D + "«0 ≤ x ≤ 7, 2» → 0 ≤ x ≤ 7,2", r"Какие целые значения принимает $x$, если $0 \le x \le 7{,}2$?")
E("G8_ALG_8_111.2", D + "«32 − 0, 5 ·» → ⁵√32 − 0,5 · ∛(−216) = 2 + 3 = 5; корни записаны формулой", r"Вычислите: $\sqrt[5]{32} - 0{,}5 \cdot \sqrt[3]{-216}$")
E("G5_TB_34_1318.6", D + "2 − 0,6 = 1,4", r"Вычислите $2 - 0{,}6$")
E("G5_TB_34_1318.3", D + "3 + 0,24 = 3,24 = 81/25", r"Вычислите $3+0{,}24$")
E("G5_TB_33_1293.3", D + "504 − 47,9 + (58,7 − 49) = 456,1 + 9,7 = 465,8", r"Выполните действия $504-47{,}9+(58{,}7-49)$")
E("G5_TB_32_1219.6", D + "425 − 2,647 = 422,353", r"Выполните действие $425-2{,}647$")
E("G5_TB_32_1219.4", D + "129 + 9,72 = 138,72", r"Выполните действие $129+9{,}72$")
E("G5_TB_33_1256.5", D + "15 − 1,12 = 13,88", r"Выполните вычитание $15-1{,}12$")
E("G9_TB_12_182.2", D + "«б. 0, 5» → k = 0,5 (ключ y = √(0,5x)); убрана оторванная метка «б.»", r"Постройте график функции $y = \sqrt{kx}$ при $k = 0{,}5$. Как меняется характер графика в зависимости от коэффициента $k$?")
E("G7_ALG_5_3.6", D + "−8,9a + 1,5b − 1,1a − 5,5b = −10a − 4b", r"Приведите подобные слагаемые: $-8{,}9a+1{,}5b-1{,}1a-5{,}5b$")
E("G7_ALG_39_9.11", D + "«2, 34·1, 9» → 2,34 · 1,9 (числовое выражение)", r"Является ли алгебраическим выражением $2{,}34 \cdot 1{,}9$?")
E("G7_ALG_6_7.3", "в условии перед числом осталась оторванная метка «5,» (номер пункта): 5,567 · 10³ = 5567", r"Запишите число, заданное в стандартном виде, в полной форме: $5{,}567 \cdot 10^{3}$")
E("G7_TB_32_826.4", D + "«9, 9²» → 9,9² = (10 − 0,1)² = 98,01", r"Используя формулу квадрата суммы или формулу квадрата разности, вычислите: $9{,}9^{2}$")
E("G9_TB_13_206_3", D + "«2x² + 1, 2x + 2» → y = 2x² + 1,2x + 2, минимум при x = −0,3: 0,18 − 0,36 + 2 = 1,82", r"Используя график, найдите множество значений функции $y = 2x^{2} + 1{,}2x + 2$")
E("G10_TB_§18_18_9_5", D + "«cos 5, 1» → cos 5,1 (5,1 рад); вариант «cos 20° > cos 5,1» совпадал с ключом — закрыт", r"Сравните $\cos 20^{\circ}$ и $\cos 5{,}1$.", drop=[2])
E("G11_TB_§5_5_58_d", D + "«ln x − 4, 5x²» → f(x) = ln x − 4,5x², f′ = 1/x − 9x = 0 при x = 1/3", r"Для функции $f(x)=\ln x-4{,}5x^{2}$ найдите промежутки непрерывности, промежутки возрастания (убывания).")
E("G8_TB_39_932.3", D + "«1, 5» → y = 1,5 (Макарычев 8 № 932 в)); ключ неверен: 5 · 1,5 = 7,5 > 2 · 0,5 + 6 = 7 — значение является решением (было «нет»); вариант «Да, …» совпадал с новым ключом — закрыт",
  r"Является ли решением неравенства $5y > 2(y - 1) + 6$ значение $y = 1{,}5$?", src="Макарычев 8 (OCR учебника) + пересчёт", k="да", drop=[0],
  dadd=[("нет", "Ученик ошибся при подстановке: 5 · 1,5 = 7,5, а 2 · (1,5 − 1) + 6 = 7, и 7,5 > 7 — неравенство верное.")])
I10 = "IDUM Алгебра 10, § 3.1 упр. 3 (скан)"
C3 = "условие приведено к тексту учебника (упр. 3): убрана метка пункта"
E("G10_TB_3_1_3_1", C3 + "; показатель −√3/2, а не −√(3/2) (знак сравнения тот же: (5/3)^{√3/2} > 1)", r"Сравните выражения: $\left(\dfrac{3}{5}\right)^{-\frac{\sqrt{3}}{2}}$ и $1$", src=I10)
E("G10_TB_3_1_3_2", C3 + "; десятичная дробь 3,2 была разорвана («3, 2^{−√2}»): 3,2^{−√2} < 1", r"Сравните выражения: $3{,}2^{-\sqrt{2}}$ и $1$", src=I10)
E("G10_TB_3_1_3_3", C3 + "; показатель √5/9, а не √(5/9) (знак тот же: √5/9 ≈ 0,25 > 1/6, основание 0,7 < 1)", r"Сравните выражения: $0{,}7^{\frac{\sqrt{5}}{9}}$ и $0{,}7^{\frac{1}{6}}$", src=I10)
E("G10_TB_3_1_3_4", C3, r"Сравните выражения: $5^{-\sqrt{13}}$ и $\left(\dfrac{1}{5}\right)^{2{,}1}$", src=I10)
# IDUM 5 ч. 2 № 521 и № 528 (bank 1521, 1528): разделитель «:» и запятые дробей склеились с числами
I5 = "IDUM 5 ч. 2 (текст PDF)"
Q521 = r"Вычислите значения произведений, если $2{,}9 \cdot 4{,}3 = 12{,}47$: $%s$"
for t, e, k in [("G5_TB_64_1521.1", r"29 \cdot 4{,}3", "124,7"), ("G5_TB_64_1521.2", r"2{,}9 \cdot 43", "124,7"), ("G5_TB_64_1521.3", r"2{,}9 \cdot 0{,}43", "1,247"),
                ("G5_TB_64_1521.5", r"2{,}9 \cdot 0{,}0043", "0,01247"), ("G5_TB_64_1521.6", r"2{,}9 \cdot 430", "1247"), ("G5_TB_64_1521.7", r"0{,}29 \cdot 0{,}43", "0,1247"), ("G5_TB_64_1521.8", r"290 \cdot 4{,}3", "1247")]:
    E(t, f"условие искажено (склеены «12,47» и следующее число, потеряно двоеточие); восстановлено по учебнику № 521; ключ {k} верен", Q521 % e, src=I5)
Q528 = r"Вычислите значения произведений, если $8{,}9 \cdot 7{,}3 = 64{,}97$: $%s$"
for t, e, k in [("G5_TB_64_1528.1", r"89 \cdot 7{,}3", "649,7"), ("G5_TB_64_1528.2", r"8{,}9 \cdot 73", "649,7"), ("G5_TB_64_1528.3", r"8{,}9 \cdot 0{,}73", "6,497"), ("G5_TB_64_1528.5", r"8{,}9 \cdot 0{,}0073", "0,06497"),
                ("G5_TB_64_1528.6", r"89 \cdot 0{,}73", "64,97"), ("G5_TB_64_1528.7", r"0{,}89 \cdot 0{,}73", "0,6497"), ("G5_TB_64_1528.8", r"890 \cdot 7{,}3", "6497")]:
    E(t, f"условие искажено (склеены «64,97» и следующее число); восстановлено по учебнику № 528; ключ {k} верен", Q528 % e, src=I5)
